  const m = matrix.length;
  const n = matrix[0].length;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const dp = [];
  for (let i = 0; i < m; i++) dp.push(new Array(n).fill(1));
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < m; i++) {
      for (let j = 0; j < n; j++) {
        for (const d of dirs) {
          const ni = i + d[0];
          const nj = j + d[1];
          if (ni >= 0 && ni < m && nj >= 0 && nj < n && matrix[ni][nj] < matrix[i][j]) {
            if (dp[ni][nj] + 1 > dp[i][j]) {
              dp[i][j] = dp[ni][nj] + 1;
              changed = true;
            }
          }
        }
      }
    }
  }
  let best = 0;
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (dp[i][j] > best) best = dp[i][j];
    }
  }
  return best;
}

function solve(matrix) {
  const m = matrix.length;
  const n = matrix[0].length;
  const memo = [];
  for (let i = 0; i < m; i++) memo.push(new Array(n).fill(0));
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const walk = (i, j) => {
    if (memo[i][j] > 0) return memo[i][j];
    let best = 1;
    for (const d of dirs) {
      const ni = i + d[0];
      const nj = j + d[1];
      if (ni >= 0 && ni < m && nj >= 0 && nj < n && matrix[ni][nj] > matrix[i][j]) {
        const candidate = 1 + walk(ni, nj);
        if (candidate > best) best = candidate;
      }
    }
    memo[i][j] = best;
    return best;
  };
  let answer = 0;
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      const here = walk(i, j);
      if (here > answer) answer = here;
    }
  }
  return answer;
}
